\begin{theorem}
If F satisfies the Hadamard-Fischer Inequalities on the subsets of $<n>$ then for $1\leq k < n$
\newline
   $(S^F_k)^2\geq \left|S^F_{k-1} S^F_{k+1}\right|$.
\end{theorem}

